set lock_timeout = '3s'; create index if not exists propiedades_catalogos_cobertura_idx on public.propiedades (fuente,estado,municipio) include (colonia,market_center,asesor_nombre); alter function public.propiedades_inventario_catalogo(text,text,text,text) set jit=off; create or replace function public.estado_filtro_canonico(valor text) returns text language sql immutable parallel safe as $$ select case when pg_catalog.lower(pg_catalog.btrim(valor)) in ('cdmx','ciudad de méxico','ciudad de mexico') then 'Ciudad de México' else valor end $$;